async function createAttendanceStaff(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const form=e.target,fd=new FormData(form),status=$('#attendanceStaffStatus'),file=fd.get('photo'),pin=String(fd.get('pin')||'');if(!/^[0-9]{4}$/.test(pin))throw new Error('PIN must contain exactly four digits.');if(!file||!file.size)throw new Error('Select a staff photo.');if(!['image/jpeg','image/png','image/webp'].includes(file.type)||file.size>8*1024*1024)throw new Error('Use JPG, PNG or WebP up to 8 MB.');let path=null;try{const ext=file.type==='image/png'?'png':file.type==='image/webp'?'webp':'jpg',bucket=cfg.STORAGE_BUCKET||'nababi-media';const up=await db.storage.from(bucket).upload('staff/'+Date.now()+'-'+Math.random().toString(36).slice(2)+'.'+ext,file,{cacheControl:'3600',upsert:false,contentType:file.type});if(up.error)throw up.error;path=up.data.path;const url=db.storage.from(bucket).getPublicUrl(path).data.publicUrl;const r=await db.rpc('admin_create_staff_pin_account',{p_full_name:String(fd.get('full_name')||'').trim(),p_photo_url:url,p_pin:pin});if(r.error)throw r.error;if(!r.data?.ok)throw new Error(r.data?.message||'Staff account creation failed.');form.reset();status.textContent=r.data.message||'Attendance account created.';await render('staff')}catch(err){if(path)await db.storage.from(cfg.STORAGE_BUCKET||'nababi-media').remove([path]);status.textContent=err.message;throw err}}
async function publishStaffAnnouncement(e){e.preventDefault();if(role!=='admin')throw new Error('Admin only.');const form=e.target,fd=new FormData(form),title=String(fd.get('title')||'').trim(),message=String(fd.get('message')||'').trim(),status=$('#staffAnnouncementStatus'),button=form.querySelector('[type="submit"]');if(!title||!message)throw new Error('Title and message are required.');const startDate=String(fd.get('starts_date')||''),startTime=String(fd.get('starts_time')||'00:00'),endDate=String(fd.get('ends_date')||''),endTime=String(fd.get('ends_time')||'23:59');const startsAt=startDate?new Date(startDate+'T'+startTime):new Date();const endsAt=endDate?new Date(endDate+'T'+endTime):null;if(Number.isNaN(startsAt.getTime())||(endsAt&&Number.isNaN(endsAt.getTime())))throw new Error('Please choose a valid date and time.');if(endsAt&&endsAt<=startsAt)throw new Error('End date and time must be after the start date and time.');if(button)button.disabled=true;if(status)status.textContent='Saving announcement…';try{const payload={title,message,starts_at:startsAt.toISOString(),ends_at:endsAt?endsAt.toISOString():null,is_active:true};const r=await db.from('staff_announcements').insert(payload);if(r.error)throw r.error;await loadStaffAnnouncements();form.reset();if(status)status.textContent='Announcement saved successfully.';}catch(err){if(status)status.textContent='Save failed: '+(err.message||'Unknown error');throw err;}finally{if(button)button.disabled=false}}

